WITH initial_candidates AS (SELECT mktcode,tgtcode,MAX(bizdate) AS bizdate FROM `newzl`.`hsj_stock_hq_basic` WHERE volume>0 GROUP BY mktcode,tgtcode), latest_metric AS (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14'), first_rank AS (SELECT c.mktcode,c.tgtcode,c.bizdate,ROW_NUMBER() OVER(ORDER BY m.volume DESC,c.mktcode,c.tgtcode) AS rn FROM initial_candidates c JOIN latest_metric m ON m.mktcode=c.mktcode AND m.tgtcode=c.tgtcode), first_top AS (SELECT * FROM first_rank WHERE rn<=10), second_rank AS (SELECT f.mktcode,f.tgtcode,f.bizdate,ROW_NUMBER() OVER(ORDER BY m.volume ASC,f.mktcode,f.tgtcode) AS rn FROM first_top f JOIN latest_metric m ON m.mktcode=f.mktcode AND m.tgtcode=f.tgtcode) SELECT mktcode,tgtcode,bizdate FROM second_rank WHERE rn<=5;
